-- READ ONLY. Before first applying 005–008: first result should have no rows; prerequisites should all be true.
-- Existing objects mean STOP and inspect which migrations already succeeded. Never rerun a successful migration.
with names(name) as (values('paid_projects'),('paid_milestones'),('paid_project_applications'),('paid_project_offers'),('paid_milestone_submissions'),('paid_milestone_reviews'),('paid_payout_authorizations'),('payment_intents'),('payment_attempts'),('payment_receipts'),('paid_work_history'),('paid_work_evidence'))
select 'relation' as object_type,name as object_name from names where to_regclass('public.'||name) is not null
union all select 'function',p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('paid_project_party','paid_milestone_party','create_paid_project','publish_paid_project','apply_paid_project','select_paid_worker','respond_paid_offer','submit_paid_milestone','review_paid_milestone','protect_paid_project_terms','protect_paid_milestone_terms','protect_paid_offer_terms','refresh_payment_wallet_locks','authorize_project_payout','prepare_milestone_payment','store_payment_template','register_signed_payment','cancel_unsigned_payment','record_payment_result','protect_payment_intent','protect_payment_attempt','initialize_paid_work_history','share_paid_work','consent_paid_work','protect_paid_history','finalize_paid_applications')
union all select 'trigger',t.tgname from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and not t.tgisinternal and t.tgname in ('paid_project_terms','paid_milestone_terms','paid_offer_terms','paid_submissions_immutable','paid_reviews_immutable','payment_intent_immutable','payment_attempt_immutable','payment_receipt_immutable','payout_authorization_immutable','paid_history_immutable','paid_history_evidence_immutable','paid_worker_accepted')
union all select 'index',c.relname from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('one_live_payment_intent','one_live_payment_attempt');
select to_regclass('public.achievement_claims') is not null as phase1_present,to_regclass('public.organizations') is not null as organizations_present,to_regclass('public.credential_proofs') is not null as v3_present,to_regclass('public.wallet_connections') is not null as wallet_ownership_present;
